.cookie-editor-react #cookie-product-panel-circle .cookie-business-hero,
.cookie-editor-react #cookie-product-panel-market .cookie-business-hero{gap:5px;padding-bottom:12px}
.cookie-editor-react #cookie-product-panel-circle .cookie-business-hero p,
.cookie-editor-react #cookie-product-panel-market .cookie-business-hero p{line-height:1.55}
.cookie-editor-react .cookie-market-page .searchbox input{border-radius:0}
.cookie-editor-react .cookie-business-channel{display:grid;gap:var(--space-2);padding:11px;border-radius:10px}
.cookie-editor-react .cookie-business-channel .cookie-business-avatar{width:30px;height:30px;border-radius:9px;font-weight:800}
.cookie-editor-react .cookie-business-channel-top{
  display:flex;align-items:center;gap:var(--space-2);min-width:0;
}
.cookie-editor-react .cookie-business-channel-top>div{flex:1;min-width:0;display:grid;gap:2px}
.cookie-editor-react .cookie-business-channel-top small{font-size:10px;color:var(--od-sub)}
.cookie-editor-react .cookie-business-channel-top .cookie-business-channel-status{
  flex:none;padding:3px 6px;border-radius:5px;background:var(--od-bg);font-size:9.5px;
}
.cookie-editor-react .cookie-business-channel>button{justify-self:end}
.cookie-editor-react .cookie-business-channel>button svg{width:12px;height:12px}
.cookie-editor-react .cookie-business-channel .cookie-business-channel-detail{
  padding:8px 9px;border-radius:7px;background:var(--od-bg);
}
.cookie-editor-react .cookie-business-circle-note{padding:11px;border:0;border-radius:9px;background:var(--od-muted);gap:5px}
.cookie-editor-react .cookie-business-circle-note>strong{font-size:11.5px}
.cookie-editor-react .cookie-business-circle-note>p{font-size:10.5px;line-height:1.65}
@media(max-width:350px){
 .cookie-editor-react .cookie-business-content{padding:var(--space-2)}
 .cookie-editor-react .cookie-business-feature{padding:var(--space-2)}
 .cookie-editor-react .cookie-business-actions{gap:var(--space-1)}
}


/* Lightweight feature catalog: direct action, no request/approval UI. */
.cookie-editor-react .cookie-market-page{gap:var(--space-2)}
.cookie-editor-react .cookie-market-page .cookie-market-resource>strong{font-size:12px;line-height:1.4}
.cookie-editor-react .cookie-market-page .cookie-market-resource-actions button svg{width:12px;height:12px}
.cookie-editor-react .cookie-market-page>.od-field{width:100%;min-width:0}
.cookie-editor-react .cookie-market-page .cookie-market-results{
  display:grid;gap:var(--space-2);border:0;
}
.cookie-editor-react .cookie-market-page .cookie-market-resource{
  min-width:0;display:grid;gap:var(--space-2);
  padding:var(--space-3);border:1px solid var(--od-line);
  border-radius:var(--radius-surface);
}
.cookie-editor-react .cookie-market-page .cookie-market-resource-actions{
  justify-content:space-between;gap:var(--space-2);flex-wrap:wrap;
}
.cookie-editor-react .cookie-market-page .cookie-market-resource-actions>small{
  color:var(--od-sub);font-size:var(--od-meta-size);
}

/* Official external subscriptions; no invented pricing or payment capture. */
.cookie-editor-react .cookie-business-membership{
  display:grid;gap:var(--space-2);min-width:0;padding:11px;margin-top:11px;
  border:1px solid var(--od-line);border-radius:10px;
}
.cookie-editor-react .cookie-business-membership-header{
  display:flex;align-items:center;justify-content:space-between;
  gap:var(--space-2);min-width:0;
}
.cookie-editor-react .cookie-business-membership-header>div{flex:1;min-width:0}
.cookie-editor-react .cookie-business-membership-header strong{font-size:12px}
.cookie-editor-react .cookie-business-membership-header p{
  margin:3px 0 0;color:var(--od-sub);font-size:10px;line-height:1.5;
}
.cookie-editor-react .cookie-business-membership-header>button{flex:none}
.cookie-editor-react .cookie-business-membership-header>button svg{width:14px;height:14px}
.cookie-editor-react .cookie-business-membership-list{
  display:grid;gap:0;min-width:0;border-top:1px solid var(--od-line);
}
.cookie-editor-react .cookie-business-membership-list>small{
  padding:var(--space-2) 0;color:var(--od-sub);font-size:var(--od-meta-size);
}
.cookie-editor-react .cookie-business-membership-row{
  display:flex;align-items:center;gap:var(--space-2);min-width:0;
  padding:var(--space-2) 0;border-bottom:1px solid var(--od-line);
}
.cookie-editor-react .cookie-business-membership-row>div{
  flex:1;min-width:0;display:grid;gap:2px;
}
.cookie-editor-react .cookie-business-membership-row>div>strong{
  font-size:var(--od-note-size);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.cookie-editor-react .cookie-business-membership-row>div>small{
  color:var(--od-sub);font-size:var(--od-meta-size);overflow-wrap:anywhere;
}
.cookie-editor-react .cookie-business-membership-row>a{
  min-height:30px;flex:none;text-decoration:none;
}
.cookie-editor-react .cookie-business-membership-list>p{
  margin:var(--space-2) 0 0;color:var(--od-sub);
