}
@media(max-width:350px){
 .cookie-editor-react .cookie-business-membership-header{gap:var(--space-1)}
 .cookie-editor-react .cookie-business-membership-header p{font-size:10px}
 .cookie-editor-react .cookie-market-page .cookie-market-resource{padding:var(--space-2)}
}


/* Explicit Cookie Expiration UI: visible before advanced attributes. */
.cookie-editor-react .cookie-expiration-compact{
  display:grid;gap:6px;min-width:0;margin:0;
  padding:9px 10px;border:1px solid var(--od-line);
  border-radius:var(--radius-control);background:var(--od-muted);
}
.cookie-editor-react .cookie-expiration-mode{
  display:grid;grid-template-columns:minmax(0,1fr) minmax(0,150px);align-items:center;
