}
.cookie-editor-react .cookie-expiration-mode>span{min-width:0}
.cookie-editor-react .cookie-expiration-compact>.cookie-expiration-mode small{display:block;font-size:10px;font-weight:450;line-height:1.35;margin-top:2px}
.cookie-editor-react .cookie-expiration-mode>.od-field{
  min-width:0;max-width:100%;height:34px;min-height:34px;font-size:11.5px;padding:5px 7px;
}
.cookie-editor-react .cookie-expiration-compact>p{
  margin:0;font-size:10px;color:var(--od-sub);line-height:1.55;
}
.cookie-editor-react .cookie-expiration-date,
.cookie-editor-react .cookie-expiration-duration{
  display:grid;gap:5px;min-width:0;padding-top:5px;border-top:1px solid var(--od-line);
