}
.cookie-editor-react .cookie-inline-editor .cookie-expiration-date>.od-field{font-size:11px}
.cookie-editor-react .cookie-expiration-compact small{
  color:var(--od-sub);font-size:10px;font-weight:400;line-height:1.55;
}
@media(max-width:350px){
 .cookie-editor-react .cookie-expiration-compact{padding:var(--space-2)}
 .cookie-editor-react .cookie-expiration-mode{grid-template-columns:minmax(0,1fr) minmax(0,130px)}
}


